import{_ as e,c as i,o as a,aj as t}from"./chunks/framework.Id7s26SP.js";const k=JSON.parse('{"title":"Admin Tokens: Scopes, Protected Apps and CI Sessions","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/admin-tokens.md","filePath":"getting-started/admin-tokens.md"}'),n={name:"getting-started/admin-tokens.md"};function o(d,s,h,p,r,l){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="admin-tokens-scopes-protected-apps-and-ci-sessions" tabindex="-1">Admin Tokens: Scopes, Protected Apps and CI Sessions <a class="header-anchor" href="#admin-tokens-scopes-protected-apps-and-ci-sessions" aria-label="Permalink to “Admin Tokens: Scopes, Protected Apps and CI Sessions”">​</a></h1><p>Every CLI login, script token and CI token is an admin session with a <strong>scope</strong>: the kinds of work it may do. A session can also be <strong>pinned</strong> to some apps, so it reaches only those. A plain login can change configuration and data on your apps, but it cannot delete them or change who has access. Apps with real users can be marked <strong>protected</strong>, so a CLI login or token must be pinned to them to change them. Give each machine, script and pipeline the narrowest token that does its job.</p><h2 id="every-login-is-a-scoped-session" tabindex="-1">Every login is a scoped session <a class="header-anchor" href="#every-login-is-a-scoped-session" aria-label="Permalink to “Every login is a scoped session”">​</a></h2><p>Sign in from the CLI:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>A plain login holds the default scope <code>read</code>, <code>write</code>, <code>data:read</code> and <code>data:write</code>, not pinned to any app. Check what the current login holds:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whoami</span></span></code></pre></div><p><code>whoami</code> shows the session&#39;s kind, its scope and the apps it is pinned to. <code>primitive logout</code> revokes the session on the server, so its refresh token stops working, and clears it from this machine.</p><h2 id="the-five-scopes" tabindex="-1">The five scopes <a class="header-anchor" href="#the-five-scopes" aria-label="Permalink to “The five scopes”">​</a></h2><p>The scopes are <code>read</code>, <code>write</code>, <code>admin</code>, <code>data:read</code> and <code>data:write</code>:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Covers</th></tr></thead><tbody><tr><td><code>read</code></td><td>Listing and reading configuration: apps, settings, functions, prompts, integrations, users</td></tr><tr><td><code>write</code></td><td>Creating and changing configuration, setting and deleting secrets, setting an app&#39;s <code>protected</code> flag, and deploying and activating functions and prompts</td></tr><tr><td><code>data:read</code></td><td>Reading documents and database records through the admin API, the app API and WebSocket connections</td></tr><tr><td><code>data:write</code></td><td>Creating, changing and deleting documents and database records</td></tr><tr><td><code>admin</code></td><td>Deleting apps, databases and users, removing collaborators, changing roles, hard deletes, and clearing an app&#39;s <code>protected</code> flag</td></tr></tbody></table><p>The data scopes guard direct access to data only. A token holding <code>write</code> can deploy and activate code, and that code reads and writes the app&#39;s data whatever the token&#39;s data scopes are. Treat <code>write</code> as able to reach data.</p><p>No scope implies another: <code>admin</code> does not include <code>read</code>, and <code>data:write</code> does not include <code>data:read</code>. A command needs every scope its route declares, and a refused command names the ones it is missing.</p><h2 id="protected-apps" tabindex="-1">Protected apps <a class="header-anchor" href="#protected-apps" aria-label="Permalink to “Protected apps”">​</a></h2><p>Mark an app that has real users as protected in its <code>app.toml</code>:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># primitive/prod/app.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">protected = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span></span></code></pre></div><p>Only the app&#39;s console owner can set or clear the flag. <code>primitive apps get</code> and the Admin Console show it.</p><p>On a protected app, a scoped login that is not pinned to the app can only read its configuration. Anything more — a <code>config push</code>, a data read, a deploy — is refused with the command that fixes it. Run that command to get a login pinned to the app:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> read,write,data:read,data:write</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">app-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>The pinned login reaches only the apps you name, so list each app you work on, separated by commas. Clearing <code>protected</code> also needs the <code>admin</code> scope, so it takes a <a href="#stepping-up-for-destructive-commands">step-up</a>.</p><p>A pin also reaches the pinned app&#39;s child apps: a login pinned to an app can work on that app&#39;s <a href="./primitive-cli.html#child-apps">child apps</a> with the scopes it holds. A pin on a child app does not reach its parent, and child apps cannot be protected.</p><h2 id="stepping-up-for-destructive-commands" tabindex="-1">Stepping up for destructive commands <a class="header-anchor" href="#stepping-up-for-destructive-commands" aria-label="Permalink to “Stepping up for destructive commands”">​</a></h2><p>Deleting an app or a database, removing a collaborator, changing a user&#39;s role and clearing <code>protected</code> need the <code>admin</code> scope, which a plain login does not hold. Ask for a step-up:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span></span></code></pre></div><p>A step-up lasts 15 minutes. It holds your login&#39;s scopes plus <code>admin</code>, pinned to the environment&#39;s app; pass <code>--app &lt;app-id&gt;</code> to pin another. Google asks you to sign in again, and the console asks you to <strong>Approve</strong> the request. The step-up is stored beside your login, which keeps working. A command refused for lacking <code>admin</code> retries once with the step-up. <code>primitive logout</code> ends both at once.</p><h2 id="a-narrower-token-for-a-script-or-an-agent" tabindex="-1">A narrower token for a script or an agent <a class="header-anchor" href="#a-narrower-token-for-a-script-or-an-agent" aria-label="Permalink to “A narrower token for a script or an agent”">​</a></h2><p>Print a token that can do less than your login:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> token</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">app-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ttl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 15m</span></span></code></pre></div><p>The token lives at most 1 hour and never longer than your login. When it is no wider than your login, it prints with no browser. A wider request, such as a scope your login lacks or a new pin that carries more than <code>read</code>, opens the approval page first.</p><h2 id="ci-sessions" tabindex="-1">CI sessions <a class="header-anchor" href="#ci-sessions" aria-label="Permalink to “CI sessions”">​</a></h2><p>For a pipeline or a server job, create a CI session from your own login:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sessions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploys</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> read,write</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">app-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><code>primitive auth sessions create</code> opens the approval page, then prints the token once. A CI session lasts 90 days unless <code>--ttl</code> says otherwise, and at most 1 year. It is always pinned, never holds <code>admin</code>, and cannot be refreshed or derive other tokens.</p><p>Store the token in your CI&#39;s secret store and run the CLI with it:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PRIMITIVE_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span></span></code></pre></div><p>A <code>read,write</code> CI session cannot read data itself, but it can deploy a function that does.</p><h2 id="listing-and-revoking-sessions" tabindex="-1">Listing and revoking sessions <a class="header-anchor" href="#listing-and-revoking-sessions" aria-label="Permalink to “Listing and revoking sessions”">​</a></h2><p>Every login, step-up and CI session is listed:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sessions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sessions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revoke</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">session-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>The list shows each session&#39;s kind, name, scope, pinned apps and status. Revoke a login on a machine you no longer use, or a CI session whose token may have leaked. A revoked CI token fails on its next request; a revoked login&#39;s refresh fails, and its access token stops within the hour.</p><h2 id="when-a-command-is-refused" tabindex="-1">When a command is refused <a class="header-anchor" href="#when-a-command-is-refused" aria-label="Permalink to “When a command is refused”">​</a></h2><p>A refused command answers 403 with a <code>code</code> and, for a missing scope or pin, prints the <code>primitive login …</code> command that grants it. A login that can no longer be refreshed answers 401 instead:</p><table tabindex="0"><thead><tr><th><code>code</code></th><th>Means</th><th>Do</th></tr></thead><tbody><tr><td><code>INSUFFICIENT_SCOPE</code></td><td>The login lacks a scope the route declares; <code>details.missing</code> names it</td><td>Run the printed <code>primitive login --scope …</code> command</td></tr><tr><td><code>APP_NOT_PINNED</code></td><td>The login&#39;s pins do not reach the app or route the command named</td><td>Check that the command targets the app you intended, then run the printed command</td></tr><tr><td><code>PROTECTED_APP_PIN_REQUIRED</code></td><td>The app is protected and the login is not pinned to it</td><td>Run the printed <code>primitive login … --app &lt;app-id&gt;</code> command</td></tr><tr><td><code>PROTECTED_FLAG_OWNER_ONLY</code></td><td>Only the app&#39;s console owner can change <code>protected</code></td><td>Ask the owner, or <code>primitive config pull --only app</code> if your <code>app.toml</code> is out of date</td></tr><tr><td><code>SESSION_UNSCOPED</code></td><td>A 401 on refresh: the login predates scoped sessions and cannot be refreshed</td><td>Run <code>primitive login</code></td></tr></tbody></table><p>A printed <code>--app</code> does not by itself mean the app is protected: <code>APP_NOT_PINNED</code> and <code>INSUFFICIENT_SCOPE</code> print it too. Read the <code>code</code>.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><strong><a href="./primitive-cli.html#authentication">Primitive CLI</a></strong> — Every login, token and session command</li><li><strong><a href="./configuring-primitive-services.html">Configuring Primitive Services</a></strong> — The <code>app.toml</code> settings and the push that carries <code>protected</code></li><li><strong><a href="./admin-console.html">Admin Console</a></strong> — Approve CLI logins and see each app&#39;s protected flag</li></ul>`,47)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
